-- Phase 1 security hardening
-- Restrict SECURITY DEFINER functions that are internal-only and harden mutable search paths.
-- Admin wrappers remain callable by the server-side service_role client only.

BEGIN;

-- Internal admin wrappers: never expose these through PostgREST/RPC to anon/authenticated.
REVOKE ALL ON FUNCTION public.admin_update_profile(uuid, uuid, text, text, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.admin_update_profile(uuid, uuid, text, text, boolean) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_update_profile(uuid, uuid, text, text, boolean) TO service_role;

REVOKE ALL ON FUNCTION public.admin_delete_user_data(uuid, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.admin_delete_user_data(uuid, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_delete_user_data(uuid, uuid) TO service_role;

-- Trigger-only functions: they are not application RPC endpoints.
REVOKE ALL ON FUNCTION public.audit_log_row_change() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.audit_log_row_change() FROM anon, authenticated;

REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.handle_new_user() TO supabase_auth_admin;

-- This trigger function does not require elevated privileges.
ALTER FUNCTION public.prevent_currency_code_update()
  SECURITY INVOKER
  SET search_path = public, pg_temp;
REVOKE ALL ON FUNCTION public.prevent_currency_code_update() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.prevent_currency_code_update() FROM anon, authenticated;

-- This helper only changes a session-local setting and is invoked by the server-side
-- service-role client. It does not need SECURITY DEFINER.
ALTER FUNCTION public.set_audit_changed_by(uuid)
  SECURITY INVOKER
  SET search_path = public, pg_temp;
REVOKE ALL ON FUNCTION public.set_audit_changed_by(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.set_audit_changed_by(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.set_audit_changed_by(uuid) TO service_role;

-- Harden helper function search paths.
ALTER FUNCTION public.audit_log_diff(jsonb, jsonb)
  SET search_path = public, pg_temp;

COMMIT;

-- Phase 1 security hardening: remove unauthenticated Data API access
BEGIN;

-- The application requires authentication before accessing the public schema.
-- RLS remains the row-level authorization boundary for authenticated users.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM anon;

COMMIT;

-- Phase 1 security hardening: bind permission checks to the current session user
BEGIN;

CREATE OR REPLACE FUNCTION public.current_user_has_permission(_permission text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
  SELECT public.has_permission(auth.uid(), _permission);
$function$;

REVOKE ALL ON FUNCTION public.current_user_has_permission(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.current_user_has_permission(text) TO authenticated, service_role;

-- Rewrite existing RLS/Storage policies to use the session-bound helper.
DO $$
DECLARE
  p record;
  using_expr text;
  check_expr text;
BEGIN
  FOR p IN
    SELECT schemaname, tablename, policyname, qual, with_check
    FROM pg_policies
    WHERE (schemaname = 'public' OR schemaname = 'storage')
      AND (coalesce(qual,'') LIKE '%has_permission(auth.uid(),%'
           OR coalesce(with_check,'') LIKE '%has_permission(auth.uid(),%')
  LOOP
    using_expr := CASE
      WHEN p.qual IS NULL THEN NULL
      ELSE replace(p.qual, 'has_permission(auth.uid(),', 'current_user_has_permission(')
    END;
    check_expr := CASE
      WHEN p.with_check IS NULL THEN NULL
      ELSE replace(p.with_check, 'has_permission(auth.uid(),', 'current_user_has_permission(')
    END;

    IF using_expr IS NOT NULL THEN
      EXECUTE format(
        'ALTER POLICY %I ON %I.%I USING (%s)',
        p.policyname, p.schemaname, p.tablename, using_expr
      );
    END IF;

    IF check_expr IS NOT NULL THEN
      EXECUTE format(
        'ALTER POLICY %I ON %I.%I WITH CHECK (%s)',
        p.policyname, p.schemaname, p.tablename, check_expr
      );
    END IF;
  END LOOP;
END $$;

-- The old helper accepted an arbitrary UUID and therefore should no longer
-- be exposed as an application RPC endpoint. RLS now uses the session-bound helper.
REVOKE EXECUTE ON FUNCTION public.has_permission(uuid, text) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.is_admin(uuid) FROM PUBLIC, anon, authenticated;

-- is_admin is retained for backwards compatibility for trusted server-side use.
GRANT EXECUTE ON FUNCTION public.has_permission(uuid, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.is_admin(uuid) TO service_role;

COMMIT;

-- Fix purchase immutability trigger semantics:
-- allow only posted -> voided on invoice header, and never delete/update invoice lines.
BEGIN;

CREATE OR REPLACE FUNCTION public.prevent_posted_invoice_edit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'purchase_invoices' THEN
    IF OLD.status = 'posted'
       AND NEW.status = 'voided'
       AND NEW.invoice_no IS NOT DISTINCT FROM OLD.invoice_no
       AND NEW.invoice_date IS NOT DISTINCT FROM OLD.invoice_date
       AND NEW.supplier_id IS NOT DISTINCT FROM OLD.supplier_id
       AND NEW.payment_type IS NOT DISTINCT FROM OLD.payment_type
       AND NEW.currency_code IS NOT DISTINCT FROM OLD.currency_code
       AND NEW.exchange_rate IS NOT DISTINCT FROM OLD.exchange_rate
       AND NEW.total_foreign IS NOT DISTINCT FROM OLD.total_foreign
       AND NEW.total_local IS NOT DISTINCT FROM OLD.total_local
       AND NEW.notes IS NOT DISTINCT FROM OLD.notes
       AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
    THEN
      RETURN NEW;
    END IF;

    IF OLD.status = 'posted' THEN
      RAISE EXCEPTION 'Posted purchase invoices are immutable; void the invoice instead';
    END IF;

    RAISE EXCEPTION 'Voided purchase invoices are immutable';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Purchase invoice lines are immutable and cannot be deleted';
  END IF;

  RAISE EXCEPTION 'Purchase invoice lines are immutable; void the invoice instead';
END;
$function$;

COMMIT;

BEGIN;
DROP TRIGGER IF EXISTS trg_prevent_posted_invoice_delete ON public.purchase_invoices;
CREATE TRIGGER trg_prevent_posted_invoice_delete
BEFORE DELETE ON public.purchase_invoices
FOR EACH ROW EXECUTE FUNCTION public.prevent_posted_invoice_edit();
COMMIT;

BEGIN;

-- Purchase creation is now a single database transaction. It validates the
-- authenticated caller, inserts the header and lines, and lets the existing
-- INSERT trigger create the authoritative purchase stock movements.
CREATE OR REPLACE FUNCTION public.create_purchase_invoice(
  _invoice_no TEXT,
  _invoice_date DATE,
  _supplier_id UUID,
  _payment_type TEXT,
  _currency_code TEXT,
  _exchange_rate NUMERIC,
  _total_foreign NUMERIC,
  _total_local NUMERIC,
  _notes TEXT,
  _items JSONB
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_invoice_id UUID;
  v_item JSONB;
  v_item_id UUID;
  v_item_unit_id UUID;
  v_quantity NUMERIC;
  v_price NUMERIC;
  v_conversion NUMERIC;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_user_has_permission('invoices.manage') THEN RAISE EXCEPTION 'Permission denied'; END IF;

  IF COALESCE(trim(_invoice_no), '') = '' THEN RAISE EXCEPTION 'Invoice number is required'; END IF;
  IF _invoice_date IS NULL THEN RAISE EXCEPTION 'Invoice date is required'; END IF;
  IF _exchange_rate IS NULL OR _exchange_rate <= 0 THEN RAISE EXCEPTION 'Exchange rate must be positive'; END IF;
  IF _total_foreign < 0 OR _total_local < 0 THEN RAISE EXCEPTION 'Invoice totals cannot be negative'; END IF;
  IF jsonb_typeof(_items) <> 'array' OR jsonb_array_length(_items) = 0 THEN RAISE EXCEPTION 'At least one invoice item is required'; END IF;

  IF EXISTS (SELECT 1 FROM public.purchase_invoices WHERE invoice_no = _invoice_no) THEN
    RAISE EXCEPTION 'Invoice number already exists';
  END IF;

  INSERT INTO public.purchase_invoices (
    invoice_no, invoice_date, supplier_id, payment_type, currency_code,
    exchange_rate, total_foreign, total_local, notes, created_by, status
  ) VALUES (
    _invoice_no, _invoice_date, _supplier_id, _payment_type, _currency_code,
    _exchange_rate, _total_foreign, _total_local, _notes, v_user, 'posted'
  )
  RETURNING id INTO v_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items)
  LOOP
    v_item_id := (v_item->>'item_id')::UUID;
    v_item_unit_id := NULLIF(v_item->>'item_unit_id','')::UUID;
    v_quantity := (v_item->>'quantity')::NUMERIC;
    v_price := (v_item->>'price_local')::NUMERIC;
    v_conversion := COALESCE(NULLIF(v_item->>'conversion_factor','')::NUMERIC, 1);

    IF v_quantity IS NULL OR v_quantity <= 0 THEN RAISE EXCEPTION 'Quantity must be positive'; END IF;
    IF v_price IS NULL OR v_price < 0 THEN RAISE EXCEPTION 'Price cannot be negative'; END IF;
    IF v_conversion <= 0 THEN RAISE EXCEPTION 'Conversion factor must be positive'; END IF;

    IF NOT EXISTS (SELECT 1 FROM public.items WHERE id = v_item_id) THEN
      RAISE EXCEPTION 'Item not found';
    END IF;

    IF v_item_unit_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.item_units
      WHERE id = v_item_unit_id AND item_id = v_item_id
    ) THEN
      RAISE EXCEPTION 'Item unit does not belong to item';
    END IF;

    INSERT INTO public.purchase_invoice_items (
      invoice_id, item_id, item_unit_id, quantity, price_local,
      conversion_factor, line_total_local, created_by
    ) VALUES (
      v_invoice_id, v_item_id, v_item_unit_id, v_quantity, v_price,
      v_conversion, COALESCE((v_item->>'line_total_local')::NUMERIC, v_quantity * v_price),
      v_user
    );

    UPDATE public.items
    SET last_purchase_price_local = v_price / v_conversion,
        updated_at = now(),
        updated_by = v_user
    WHERE id = v_item_id;
  END LOOP;

  RETURN v_invoice_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_purchase_invoice(TEXT,DATE,UUID,TEXT,TEXT,NUMERIC,NUMERIC,NUMERIC,TEXT,JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_purchase_invoice(TEXT,DATE,UUID,TEXT,TEXT,NUMERIC,NUMERIC,NUMERIC,TEXT,JSONB) TO authenticated, service_role;

-- Prevent direct clients from writing authoritative stock movements.
DROP POLICY IF EXISTS "perm write stock_movements" ON public.stock_movements;
DROP POLICY IF EXISTS "perm insert stock_movements" ON public.stock_movements;
DROP POLICY IF EXISTS "perm update stock_movements" ON public.stock_movements;
DROP POLICY IF EXISTS "perm delete stock_movements" ON public.stock_movements;

CREATE POLICY "stock movements read"
ON public.stock_movements FOR SELECT TO authenticated
USING (true);

COMMIT;

BEGIN;

-- Inventory is derived from immutable stock movements.
-- Serialize writes per item and reject any purchase that would make stock negative.
CREATE OR REPLACE FUNCTION public.on_invoice_item_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_invoice public.purchase_invoices%ROWTYPE;
  v_factor NUMERIC(18,6) := COALESCE(NEW.conversion_factor, 1);
  v_base_qty NUMERIC(18,4);
  v_base_price NUMERIC(18,4);
  v_current NUMERIC(18,4);
BEGIN
  IF v_factor <= 0 OR NEW.quantity <= 0 THEN
    RAISE EXCEPTION 'Purchase quantity and conversion factor must be positive';
  END IF;

  SELECT * INTO v_invoice
  FROM public.purchase_invoices
  WHERE id = NEW.invoice_id
  FOR SHARE;

  IF v_invoice.status <> 'posted' THEN
    RAISE EXCEPTION 'Only posted purchase invoices can create stock movements';
  END IF;

  -- Transaction-level advisory lock prevents concurrent writes for the same item.
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.item_id::text, 0));

  v_base_qty := NEW.quantity * v_factor;
  v_base_price := NEW.price_local / v_factor;

  SELECT COALESCE(SUM(sm.quantity), 0)
  INTO v_current
  FROM public.stock_movements sm
  WHERE sm.item_id = NEW.item_id;

  -- Purchase is positive, so it cannot itself create negative stock.
  -- This lock establishes the serialization point used by future outbound
  -- movement functions as well.
  INSERT INTO public.stock_movements (
    item_id, movement_type, quantity, unit_price_local,
    reference_table, reference_id, movement_date, created_by
  ) VALUES (
    NEW.item_id, 'purchase', v_base_qty, v_base_price,
    'purchase_invoices', NEW.invoice_id, v_invoice.invoice_date, v_invoice.created_by
  );

  UPDATE public.item_units
  SET last_purchase_price_local = NEW.price_local, updated_at = now()
  WHERE id = NEW.item_unit_id AND NEW.item_unit_id IS NOT NULL;

  UPDATE public.items
  SET last_purchase_price_local = v_base_price, updated_at = now()
  WHERE id = NEW.item_id;

  RETURN NEW;
END;
$function$;

-- Void must use the same per-item lock and must never allow stock to go below zero.
CREATE OR REPLACE FUNCTION public.void_purchase_invoice(_invoice_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_invoice public.purchase_invoices%ROWTYPE;
  v_user UUID := auth.uid();
  v_item RECORD;
  v_current NUMERIC(18,4);
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_user_has_permission('invoices.manage') THEN RAISE EXCEPTION 'Permission denied'; END IF;

  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice not found'; END IF;
  IF v_invoice.status = 'voided' THEN RAISE EXCEPTION 'Purchase invoice is already voided'; END IF;

  FOR v_item IN
    SELECT item_id, SUM(quantity * COALESCE(conversion_factor,1)) AS qty
    FROM public.purchase_invoice_items
    WHERE invoice_id = v_invoice.id
    GROUP BY item_id
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_item.item_id::text, 0));

    SELECT COALESCE(SUM(sm.quantity), 0) INTO v_current
    FROM public.stock_movements sm
    WHERE sm.item_id = v_item.item_id;

    IF v_current - v_item.qty < 0 THEN
      RAISE EXCEPTION 'Cannot void purchase: item % would result in negative stock', v_item.item_id;
    END IF;
  END LOOP;

  INSERT INTO public.stock_movements (
    item_id, movement_type, quantity, unit_price_local,
    reference_table, reference_id, movement_date, notes, created_by
  )
  SELECT pii.item_id,
         'purchase_void',
         -(pii.quantity * COALESCE(pii.conversion_factor,1)),
         CASE WHEN COALESCE(pii.conversion_factor,1) > 0
              THEN pii.price_local / pii.conversion_factor ELSE pii.price_local END,
         'purchase_invoices', v_invoice.id, v_invoice.invoice_date,
         'Void purchase invoice', v_user
  FROM public.purchase_invoice_items pii
  WHERE pii.invoice_id = v_invoice.id;

  PERFORM set_config('app.purchase_voiding', 'on', true);

  UPDATE public.purchase_invoices
  SET status='voided', voided_at=now(), voided_by=v_user, updated_by=v_user, updated_at=now()
  WHERE id=v_invoice.id;

  RETURN;
END;
$function$;

COMMIT;

BEGIN;

CREATE UNIQUE INDEX IF NOT EXISTS stock_movements_reference_item_once_idx
ON public.stock_movements (movement_type, reference_table, reference_id, item_id)
WHERE reference_table IS NOT NULL AND reference_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.adjust_stock(
  _operation_id UUID,
  _item_id UUID,
  _quantity_delta NUMERIC,
  _unit_price_local NUMERIC,
  _movement_date DATE,
  _notes TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_current NUMERIC(18,4);
  v_id UUID;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_user_has_permission('items.manage') THEN RAISE EXCEPTION 'Permission denied'; END IF;
  IF _operation_id IS NULL THEN RAISE EXCEPTION 'Operation id is required'; END IF;
  IF _item_id IS NULL THEN RAISE EXCEPTION 'Item is required'; END IF;
  IF _quantity_delta IS NULL OR _quantity_delta = 0 THEN RAISE EXCEPTION 'Adjustment quantity cannot be zero'; END IF;
  IF _unit_price_local IS NULL OR _unit_price_local < 0 THEN RAISE EXCEPTION 'Unit price cannot be negative'; END IF;
  IF _movement_date IS NULL THEN RAISE EXCEPTION 'Movement date is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.items WHERE id = _item_id) THEN RAISE EXCEPTION 'Item not found'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(_item_id::text, 0));

  IF EXISTS (
    SELECT 1 FROM public.stock_movements
    WHERE movement_type='adjustment'
      AND reference_table='stock_adjustments'
      AND reference_id=_operation_id
      AND item_id=_item_id
  ) THEN
    SELECT id INTO v_id FROM public.stock_movements
    WHERE movement_type='adjustment'
      AND reference_table='stock_adjustments'
      AND reference_id=_operation_id
      AND item_id=_item_id;
    RETURN v_id;
  END IF;

  SELECT COALESCE(SUM(quantity),0) INTO v_current
  FROM public.stock_movements
  WHERE item_id=_item_id;

  IF v_current + _quantity_delta < 0 THEN
    RAISE EXCEPTION 'Adjustment would result in negative stock';
  END IF;

  INSERT INTO public.stock_movements (
    item_id, movement_type, quantity, unit_price_local,
    reference_table, reference_id, movement_date, notes, created_by
  ) VALUES (
    _item_id, 'adjustment', _quantity_delta, _unit_price_local,
    'stock_adjustments', _operation_id, _movement_date, _notes, v_user
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.adjust_stock(UUID,UUID,NUMERIC,NUMERIC,DATE,TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.adjust_stock(UUID,UUID,NUMERIC,NUMERIC,DATE,TEXT) TO authenticated, service_role;

-- The stock ledger remains append-only; clients may read but not write it directly.
ALTER TABLE public.stock_movements ENABLE ROW LEVEL SECURITY;

COMMIT;

BEGIN;
COMMENT ON FUNCTION public.adjust_stock(UUID,UUID,NUMERIC,NUMERIC,DATE,TEXT)
IS 'Atomic, permission-checked, serialized and idempotent stock adjustment. Negative resulting stock is rejected.';
COMMIT;

BEGIN;

-- stock_movements is an append-only ledger. No client role may mutate it directly.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
ON TABLE public.stock_movements
FROM anon, authenticated;

GRANT SELECT ON TABLE public.stock_movements TO authenticated;

COMMIT;

BEGIN;

CREATE TABLE IF NOT EXISTS public.supplier_transactions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  supplier_id UUID NOT NULL REFERENCES public.suppliers(id) ON DELETE RESTRICT,
  transaction_type TEXT NOT NULL CHECK (transaction_type IN ('debit','credit')),
  amount NUMERIC(18,4) NOT NULL CHECK (amount > 0),
  currency_code TEXT NOT NULL REFERENCES public.currencies(code),
  exchange_rate NUMERIC(18,6) NOT NULL CHECK (exchange_rate > 0),
  amount_local NUMERIC(18,4) NOT NULL CHECK (amount_local > 0),
  reference_table TEXT,
  reference_id UUID,
  invoice_ref TEXT,
  payment_method TEXT,
  notes TEXT,
  transaction_date DATE NOT NULL DEFAULT CURRENT_DATE,
  created_by UUID REFERENCES public.profiles(id),
  updated_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_supplier_tx_supplier_date
ON public.supplier_transactions(supplier_id, transaction_date, created_at);

CREATE INDEX IF NOT EXISTS idx_supplier_tx_reference
ON public.supplier_transactions(reference_table, reference_id);

ALTER TABLE public.supplier_transactions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "supplier transactions read" ON public.supplier_transactions;
DROP POLICY IF EXISTS "supplier transactions write" ON public.supplier_transactions;
DROP POLICY IF EXISTS "supplier transactions update" ON public.supplier_transactions;
DROP POLICY IF EXISTS "supplier transactions delete" ON public.supplier_transactions;

CREATE POLICY "supplier transactions read"
ON public.supplier_transactions FOR SELECT TO authenticated
USING (public.current_user_has_permission('suppliers.view'));

REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
ON public.supplier_transactions FROM anon, authenticated;

GRANT SELECT ON public.supplier_transactions TO authenticated;

CREATE OR REPLACE VIEW public.supplier_balances
WITH (security_invoker = true)
AS
SELECT
  s.id AS supplier_id,
  s.name,
  s.phone,
  COALESCE(SUM(CASE WHEN st.transaction_type='debit' THEN st.amount_local ELSE 0 END),0) AS total_debit,
  COALESCE(SUM(CASE WHEN st.transaction_type='credit' THEN st.amount_local ELSE 0 END),0) AS total_credit,
  COALESCE(SUM(CASE WHEN st.transaction_type='debit' THEN st.amount_local ELSE -st.amount_local END),0) AS balance
FROM public.suppliers s
LEFT JOIN public.supplier_transactions st ON st.supplier_id=s.id
GROUP BY s.id, s.name, s.phone;

GRANT SELECT ON public.supplier_balances TO authenticated;

COMMIT;

BEGIN;

CREATE OR REPLACE FUNCTION public.create_purchase_invoice(
  _invoice_no TEXT, _invoice_date DATE, _supplier_id UUID, _payment_type TEXT,
  _currency_code TEXT, _exchange_rate NUMERIC, _total_foreign NUMERIC,
  _total_local NUMERIC, _notes TEXT, _items JSONB
)
RETURNS UUID LANGUAGE plpgsql SECURITY INVOKER
SET search_path = public, pg_temp AS $function$
DECLARE
  v_user UUID := auth.uid(); v_invoice_id UUID; v_item JSONB;
  v_item_id UUID; v_item_unit_id UUID; v_quantity NUMERIC; v_price NUMERIC; v_conversion NUMERIC;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_user_has_permission('invoices.manage') THEN RAISE EXCEPTION 'Permission denied'; END IF;
  IF _payment_type NOT IN ('cash','credit') THEN RAISE EXCEPTION 'Invalid payment type'; END IF;
  IF _supplier_id IS NULL THEN RAISE EXCEPTION 'Supplier is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id=_supplier_id) THEN RAISE EXCEPTION 'Supplier not found'; END IF;
  IF _payment_type='credit' AND _supplier_id IS NULL THEN RAISE EXCEPTION 'Credit purchase requires supplier'; END IF;
  IF COALESCE(trim(_invoice_no),'')='' THEN RAISE EXCEPTION 'Invoice number is required'; END IF;
  IF _exchange_rate IS NULL OR _exchange_rate<=0 THEN RAISE EXCEPTION 'Exchange rate must be positive'; END IF;
  IF _total_foreign<0 OR _total_local<0 THEN RAISE EXCEPTION 'Invoice totals cannot be negative'; END IF;
  IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)=0 THEN RAISE EXCEPTION 'At least one invoice item is required'; END IF;
  IF EXISTS (SELECT 1 FROM public.purchase_invoices WHERE invoice_no=_invoice_no) THEN RAISE EXCEPTION 'Invoice number already exists'; END IF;

  INSERT INTO public.purchase_invoices(invoice_no,invoice_date,supplier_id,payment_type,currency_code,exchange_rate,total_foreign,total_local,notes,created_by,status)
  VALUES(_invoice_no,_invoice_date,_supplier_id,_payment_type,_currency_code,_exchange_rate,_total_foreign,_total_local,_notes,v_user,'posted')
  RETURNING id INTO v_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_item_id := (v_item->>'item_id')::UUID;
    v_item_unit_id := NULLIF(v_item->>'item_unit_id','')::UUID;
    v_quantity := (v_item->>'quantity')::NUMERIC;
    v_price := (v_item->>'price_local')::NUMERIC;
    v_conversion := COALESCE(NULLIF(v_item->>'conversion_factor','')::NUMERIC,1);
    IF v_quantity IS NULL OR v_quantity<=0 THEN RAISE EXCEPTION 'Quantity must be positive'; END IF;
    IF v_price IS NULL OR v_price<0 THEN RAISE EXCEPTION 'Price cannot be negative'; END IF;
    IF v_conversion<=0 THEN RAISE EXCEPTION 'Conversion factor must be positive'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.items WHERE id=v_item_id) THEN RAISE EXCEPTION 'Item not found'; END IF;
    IF v_item_unit_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.item_units WHERE id=v_item_unit_id AND item_id=v_item_id) THEN RAISE EXCEPTION 'Item unit does not belong to item'; END IF;
    INSERT INTO public.purchase_invoice_items(invoice_id,item_id,item_unit_id,quantity,price_local,conversion_factor,line_total_local,created_by)
    VALUES(v_invoice_id,v_item_id,v_item_unit_id,v_quantity,v_price,v_conversion,COALESCE((v_item->>'line_total_local')::NUMERIC,v_quantity*v_price),v_user);
    UPDATE public.items SET last_purchase_price_local=v_price/v_conversion,updated_at=now(),updated_by=v_user WHERE id=v_item_id;
  END LOOP;

  IF _payment_type='credit' THEN
    INSERT INTO public.supplier_transactions(supplier_id,transaction_type,amount,currency_code,exchange_rate,amount_local,reference_table,reference_id,invoice_ref,notes,transaction_date,created_by)
    VALUES(_supplier_id,'debit',_total_foreign,_currency_code,_exchange_rate,_total_local,'purchase_invoices',v_invoice_id,_invoice_no,'Credit purchase',_invoice_date,v_user);
  END IF;

  RETURN v_invoice_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.void_purchase_invoice(_invoice_id UUID)
RETURNS VOID LANGUAGE plpgsql SECURITY INVOKER
SET search_path=public,pg_temp AS $function$
DECLARE v_user UUID:=auth.uid(); v_invoice public.purchase_invoices%ROWTYPE; v_item RECORD; v_current NUMERIC;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_user_has_permission('invoices.manage') THEN RAISE EXCEPTION 'Permission denied'; END IF;
  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id=_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice not found'; END IF;
  IF v_invoice.status='voided' THEN RAISE EXCEPTION 'Purchase invoice is already voided'; END IF;
  FOR v_item IN SELECT item_id,SUM(quantity*COALESCE(conversion_factor,1)) qty FROM public.purchase_invoice_items WHERE invoice_id=v_invoice.id GROUP BY item_id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_item.item_id::text,0));
    SELECT COALESCE(SUM(quantity),0) INTO v_current FROM public.stock_movements WHERE item_id=v_item.item_id;
    IF v_current-v_item.qty<0 THEN RAISE EXCEPTION 'Cannot void purchase: item % would result in negative stock',v_item.item_id; END IF;
  END LOOP;
  INSERT INTO public.stock_movements(item_id,movement_type,quantity,unit_price_local,reference_table,reference_id,movement_date,notes,created_by)
  SELECT item_id,'purchase_void',-(quantity*COALESCE(conversion_factor,1)),
         price_local/NULLIF(conversion_factor,0),'purchase_invoices',v_invoice.id,v_invoice.invoice_date,'Void purchase invoice',v_user
  FROM public.purchase_invoice_items WHERE invoice_id=v_invoice.id;
  IF v_invoice.payment_type='credit' THEN
    INSERT INTO public.supplier_transactions(supplier_id,transaction_type,amount,currency_code,exchange_rate,amount_local,reference_table,reference_id,invoice_ref,notes,transaction_date,created_by)
    VALUES(v_invoice.supplier_id,'credit',v_invoice.total_foreign,v_invoice.currency_code,v_invoice.exchange_rate,v_invoice.total_local,'purchase_invoices',v_invoice.id,v_invoice.invoice_no,'Void credit purchase',v_invoice.invoice_date,v_user);
  END IF;
  PERFORM set_config('app.purchase_voiding','on',true);
  UPDATE public.purchase_invoices SET status='voided',voided_at=now(),voided_by=v_user,updated_by=v_user,updated_at=now() WHERE id=v_invoice.id;
END; $function$;

COMMIT;

